import math

def drive(me, enemy, arena):
    try:
        t = arena.time
        dx = enemy.x - me.x
        dy = enemy.y - me.y
        dist = math.hypot(dx, dy)
        b = bearing_to(enemy.x, enemy.y)
        if me.righting or me.on_side:
            return (0.0, 0.0)
        if me.inverted:
            if abs(b) > 150:
                return (0.0, 0.0)
            return (0.4, -0.4)
        if dist > 0.15 and abs(b) > 4:
            s = 1.0 if abs(b) <= 60 else 0.55
            if b > 0:
                return (-s, s)
            return (s, -s)
        if dist > 1.6:
            return (1.0, 1.0)
        if dist > 1.0:
            return (0.7, 0.7)
        return (0.3, 0.3)
    except Exception:
        return (0.0, 0.0)

def weapons(me, enemy, arena):
    try:
        if me.inverted or me.on_side:
            if me.righting:
                return None
            return [self_right()]
        if me.righting:
            return None
        out = []
        b = bearing_to(enemy.x, enemy.y)
        dist = math.hypot(enemy.x - me.x, enemy.y - me.y)
        h = me.weapons.get("top")
        if h is not None:
            st = h.get("state")
            if st == "ready" and abs(b) < 35 and dist < 2.6:
                out.append(swing("top"))
        c = me.weapons.get("front")
        if c is not None:
            cl = c.get("state")
            if cl == "holding":
                out.append(release("front"))
            elif cl == "open" and dist < 1.5 and abs(b) < 45:
                out.append(grab("front"))
            elif cl == "closed" and dist > 1.7:
                out.append(release("front"))
        if not out:
            return None
        return out
    except Exception:
        return None

